package com.vmartis.matchgateway.gateway.verification.infra

import org.springframework.boot.context.properties.ConfigurationProperties
import org.springframework.boot.context.properties.EnableConfigurationProperties
import org.springframework.context.annotation.Bean
import org.springframework.context.annotation.Configuration
import org.springframework.core.io.Resource

/** The HMAC key is generated by keygen into the gateway-keys volume, never in the repo (ADR-008, CLAUDE.md §4). */
@ConfigurationProperties("app.idempotency")
data class IdempotencyProperties(
    val hmacKeyLocation: Resource,
)

@Configuration
@EnableConfigurationProperties(IdempotencyProperties::class)
class IdempotencyConfig {
    @Bean
    fun fingerprinter(properties: IdempotencyProperties) = Fingerprinter(properties.hmacKeyLocation.contentAsByteArray)
}
